        note='Residence rent; no supported home-office allocation.'
    elif 'H-E-B' in d:
        note='Groceries; no documented business meal component.'
    elif 'VENMO: WEDDING' in d:
        note='Personal wedding gift.'
    out.append({'date':date,'description':d,'amount':f'{a:.2f}','classification':c,'schedule_c_line':line,'note':note})
with (root/'deliverable/classification.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['date','description','amount','classification','schedule_c_line','note']); w.writeheader();w.writerows(out)
